#include <iostream>
using namespace std;

int main() {
    long long n, k;
    cin >> n >> k;
    long long survivor = 0;
    for (long long size = 2; size <= n; size++) {
        survivor = (survivor + k) % size;
    }
    cout << survivor + 1 << endl;
    return 0;
}

code.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        long k = in.nextLong();
        long survivor = 0;
        for (long size = 2; size <= n; size++) {
            survivor = (survivor + k) % size;
        }
        System.out.println(survivor + 1);
    }
}
